function profile=mpK10ValidateProfile(profile)
%MPK10VALIDATEPROFILE Canonical global PDP, without adjusting its power.
assert(isstruct(profile)&&isscalar(profile)&&all(isfield(profile, ...
    {'id','delayedSamples','powers'})),'MpK10:Profile','A named global PDP is required.');
d=double(profile.delayedSamples(:).');p=double(profile.powers(:).');
assert(~isempty(d)&&numel(d)==numel(p)&&all(isfinite(d))&& ...
    all(d>=0)&&all(d==fix(d))&&numel(unique(d))==numel(d), ...
    'MpK10:Delay','Scatter delays must be unique nonnegative integer samples.');
assert(all(isfinite(p))&&all(p>0)&&abs(sum(p)-1)<1e-12, ...
    'MpK10:Pdp','Diffuse PDP powers must be positive and already sum to one.');
profile.delayedSamples=d;profile.powers=p;
if ~isfield(profile,'losPhaseRad'),profile.losPhaseRad=0;end
assert(isscalar(profile.losPhaseRad)&&isfinite(profile.losPhaseRad), ...
    'MpK10:Phase','LOS phase must be a finite scalar.');
end
